<script setup lang="ts">
import { Head, useForm, router } from '@inertiajs/vue3'
import { ref } from 'vue'
import ConfirmDialog from '../../Components/ConfirmDialog.vue'
const props=defineProps<{user:any;devices:any;rooms:any;whois:any;media:any;mediaUsage:any;ratelimit:any;supportsLocked:boolean}>()
const tab=ref('info'),confirm=ref(false),pending=ref<(()=>void)|null>(null),confirmTitle=ref('تأیید عملیات'),confirmMessage=ref('آیا مطمئن هستید؟')
const edit=useForm({displayname:props.user.displayname||'',admin:!!props.user.admin,deactivated:!!props.user.deactivated,locked:!!props.user.locked})
const limit=useForm({messages_per_second:props.ratelimit.messages_per_second||0,burst_count:props.ratelimit.burst_count||0})
const password=useForm({new_password:'',logout_devices:true})
const ask=(title:string,message:string,action:()=>void)=>{confirmTitle.value=title;confirmMessage.value=message;pending.value=action;confirm.value=true}
const run=()=>pending.value?.()
</script>
<template><Head :title="user.name"/><v-container fluid class="pa-6"><div class="d-flex align-center mb-5"><v-btn icon="mdi-arrow-right" variant="text" href="/users"/><div><h1 class="text-h5">{{ user.displayname||user.name }}</h1><div class="text-caption text-medium-emphasis">{{ user.name }}</div></div></div><v-card rounded="xl"><v-tabs v-model="tab" color="primary" show-arrows><v-tab value="info">اطلاعات</v-tab><v-tab value="devices">دستگاه‌ها</v-tab><v-tab value="rooms">اتاق‌ها</v-tab><v-tab value="media">مدیا</v-tab><v-tab value="limits">محدودیت‌ها</v-tab><v-tab value="sessions">نشست‌ها و IP</v-tab></v-tabs><v-divider/><v-window v-model="tab"><v-window-item value="info"><v-card-text><v-form @submit.prevent="edit.put('/users/'+encodeURIComponent(user.name))"><v-text-field v-model="edit.displayname" label="نام نمایشی"/><v-switch v-model="edit.admin" label="مدیر سرور"/><v-switch v-model="edit.deactivated" label="غیرفعال"/><v-switch v-model="edit.locked" label="قفل‌شده" :disabled="!supportsLocked"/><v-btn type="submit" color="primary" :loading="edit.processing">ذخیره تغییرات</v-btn></v-form><v-divider class="my-6"/><v-form @submit.prevent="password.post('/users/'+encodeURIComponent(user.name)+'/reset-password')"><h3 class="text-subtitle-1 mb-2">بازنشانی گذرواژه</h3><v-text-field v-model="password.new_password" label="گذرواژه جدید" type="password" autocomplete="new-password"/><v-checkbox v-model="password.logout_devices" label="خروج از همه دستگاه‌ها"/><v-btn color="warning" :disabled="password.new_password.length<12" @click="ask('بازنشانی گذرواژه','گذرواژه کاربر تغییر می‌کند.',()=>password.post('/users/'+encodeURIComponent(user.name)+'/reset-password'))">بازنشانی</v-btn></v-form><div class="d-flex flex-wrap ga-2 mt-5"><v-btn v-if="!user.shadow_banned" color="warning" variant="tonal" @click="ask('Shadow Ban','کاربر به‌صورت نامحسوس محدود می‌شود.',()=>router.post('/users/'+encodeURIComponent(user.name)+'/shadow-ban'))">Shadow Ban</v-btn><v-btn v-else color="success" variant="tonal" @click="ask('لغو Shadow Ban','محدودیت نامحسوس کاربر برداشته می‌شود.',()=>router.delete('/users/'+encodeURIComponent(user.name)+'/shadow-ban'))">لغو Shadow Ban</v-btn><v-btn color="error" variant="tonal" @click="ask('غیرفعال‌سازی حساب','دسترسی کاربر قطع می‌شود.',()=>router.post('/users/'+encodeURIComponent(user.name)+'/deactivate'))">غیرفعال‌سازی</v-btn></div></v-card-text></v-window-item><v-window-item value="devices"><v-card-text><v-list><v-list-item v-for="d in (devices.devices||[])" :key="d.device_id" :title="d.display_name||d.device_id" :subtitle="d.last_seen_ip+' · '+new Date(d.last_seen_ts).toLocaleString()"><template #append><v-btn icon="mdi-delete" color="error" variant="text" @click="ask('حذف دستگاه','نشست این دستگاه حذف می‌شود.',()=>router.delete('/users/'+encodeURIComponent(user.name)+'/devices/'+encodeURIComponent(d.device_id)))"/></template></v-list-item></v-list></v-card-text></v-window-item><v-window-item value="rooms"><v-card-text><v-chip v-for="id in (rooms.joined_rooms||[])" :key="id" class="ma-1">{{ id }}</v-chip><v-alert v-if="!(rooms.joined_rooms||[]).length" type="info" variant="tonal">اتاقی یافت نشد.</v-alert></v-card-text></v-window-item><v-window-item value="media"><v-card-text><div>تعداد فایل‌ها: {{ media.total??0 }} · مصرف کل: {{ mediaUsage.total_bytes??0 }} بایت</div><v-list><v-list-item v-for="m in (media.media||[])" :key="m.media_id" :title="m.upload_name||m.media_id" :subtitle="(m.media_length||0)+' bytes · '+m.media_type"/></v-list><v-btn color="error" variant="tonal" @click="ask('حذف تمام مدیای کاربر','فایل‌های محلی بارگذاری‌شده توسط کاربر حذف خواهند شد.',()=>router.delete('/users/'+encodeURIComponent(user.name)+'/media'))">حذف مدیا</v-btn></v-card-text></v-window-item><v-window-item value="limits"><v-card-text><v-form @submit.prevent="limit.post('/users/'+encodeURIComponent(user.name)+'/ratelimit')"><v-text-field v-model.number="limit.messages_per_second" type="number" label="پیام در ثانیه"/><v-text-field v-model.number="limit.burst_count" type="number" label="Burst count"/><v-btn type="submit" color="primary">ذخیره محدودیت</v-btn><v-btn class="ml-2" variant="text" @click="ask('حذف Rate Limit Override','تنظیم اختصاصی محدودیت پیام حذف می‌شود.',()=>router.post('/users/'+encodeURIComponent(user.name)+'/ratelimit',{remove:true}))">حذف Override</v-btn></v-form></v-card-text></v-window-item><v-window-item value="sessions"><v-card-text><pre class="text-wrap">{{ JSON.stringify(whois,null,2) }}</pre></v-card-text></v-window-item></v-window></v-card><ConfirmDialog v-model="confirm" :title="confirmTitle" :message="confirmMessage" danger @confirm="run"/></v-container></template>
